insert into public.events (id, slug, venue_id, title, description, image_url, category, promoter_name, starts_at, doors_at, status) values
  ('5b000000-0000-4000-8000-000000000001', 'sample-the-velvet-hour', '5a000000-0000-4000-8000-000000000002', 'The Velvet Hour', 'A sharp two-hander about an old flame turning up at closing time. 90 minutes, no interval. Sample event for testing, not a real show.', '/sample/theatre.jpg', 'Theatre', 'Riverside Productions', date_trunc('day', now() at time zone 'Europe/London' + interval '3 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '3 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000002', 'sample-late-laughs-friday-showcase', '5a000000-0000-4000-8000-000000000001', 'Late Laughs: Friday Showcase', 'Four comics, one compere, tight 15-minute sets. Strong language. Sample event for testing, not a real show.', '/sample/comedy.jpg', 'Comedy', 'Lantern Comedy', date_trunc('day', now() at time zone 'Europe/London' + interval '2 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '2 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000003', 'sample-brass-bones', '5a000000-0000-4000-8000-000000000003', 'Brass & Bones', 'Eight-piece brass band playing funk and soul covers until late. Sample event for testing, not a real show.', '/sample/music.jpg', 'Gig', 'Basement Live', date_trunc('day', now() at time zone 'Europe/London' + interval '5 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '5 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000004', 'sample-midweek-jazz-sessions', '5a000000-0000-4000-8000-000000000001', 'Midweek Jazz Sessions', 'Trio sets from rising players, table seating, bar open throughout. Sample event for testing, not a real show.', '/sample/jazz.jpg', 'Jazz', 'Lantern Rooms', date_trunc('day', now() at time zone 'Europe/London' + interval '1 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '1 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000005', 'sample-a-room-with-no-view', '5a000000-0000-4000-8000-000000000002', 'A Room With No View', 'A new comedy about four flatmates and one very small kitchen. Sample event for testing, not a real show.', '/sample/theatre.jpg', 'Theatre', 'Riverside Productions', date_trunc('day', now() at time zone 'Europe/London' + interval '9 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '9 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000006', 'sample-open-mic-mayhem', '5a000000-0000-4000-8000-000000000003', 'Open Mic Mayhem', 'New acts and a few surprise headliners. Expect the unexpected. Sample event for testing, not a real show.', '/sample/comedy.jpg', 'Comedy', 'Basement Live', date_trunc('day', now() at time zone 'Europe/London' + interval '6 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '6 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000007', 'sample-northern-soul-all-nighter', '5a000000-0000-4000-8000-000000000004', 'Northern Soul All-Nighter', 'DJs spinning rare soul till 3am. Bring your talc. Sample event for testing, not a real show.', '/sample/neighbourhood.jpg', 'Club night', 'Canal Street Events', date_trunc('day', now() at time zone 'Europe/London' + interval '10 days') at time zone 'Europe/London' + interval '22 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '10 days') at time zone 'Europe/London' + interval '22 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000008', 'sample-the-unplugged-sessions', '5a000000-0000-4000-8000-000000000004', 'The Unplugged Sessions', 'Stripped-back acoustic sets from three touring singer-songwriters. Sample event for testing, not a real show.', '/sample/music.jpg', 'Gig', 'Canal Street Events', date_trunc('day', now() at time zone 'Europe/London' + interval '4 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '4 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000009', 'sample-improv-night-make-it-up', '5a000000-0000-4000-8000-000000000004', 'Improv Night: Make It Up', 'Suggestions from the crowd, scenes built on the spot. Sample event for testing, not a real show.', '/sample/comedy.jpg', 'Comedy', 'Canal Street Events', date_trunc('day', now() at time zone 'Europe/London' + interval '12 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '12 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000010', 'sample-harbour-lights-orchestra', '5a000000-0000-4000-8000-000000000005', 'Harbour Lights Orchestra', 'A chamber orchestra plays film scores by candlelight. Sample event for testing, not a real show.', '/sample/jazz.jpg', 'Classical', 'Wharf Stage', date_trunc('day', now() at time zone 'Europe/London' + interval '7 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '7 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000011', 'sample-saturday-night-floorfillers', '5a000000-0000-4000-8000-000000000005', 'Saturday Night Floorfillers', 'Pop, disco and 00s anthems. Over 18s. Sample event for testing, not a real show.', '/sample/neighbourhood.jpg', 'Club night', 'Wharf Stage', date_trunc('day', now() at time zone 'Europe/London' + interval '11 days') at time zone 'Europe/London' + interval '22 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '11 days') at time zone 'Europe/London' + interval '22 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000012', 'sample-quiz-tunes', '5a000000-0000-4000-8000-000000000006', 'Quiz & Tunes', 'Six rounds, a music round and a prize bar tab for the winners. Sample event for testing, not a real show.', null, 'Quiz night', 'Arcade Studio', date_trunc('day', now() at time zone 'Europe/London' + interval '0 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '0 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000013', 'sample-crowd-pleasers-live', '5a000000-0000-4000-8000-000000000006', 'Crowd Pleasers Live', 'Two local bands and a headline set of singalong favourites. Sample event for testing, not a real show.', '/sample/music.jpg', 'Gig', 'Arcade Studio', date_trunc('day', now() at time zone 'Europe/London' + interval '8 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '8 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000014', 'sample-the-glass-menagerie-reimagined', '5a000000-0000-4000-8000-000000000002', 'The Glass Menagerie Reimagined', 'A fresh staging of the classic memory play. This run has sold out. Sample event for testing, not a real show.', '/sample/theatre.jpg', 'Theatre', 'Riverside Productions', date_trunc('day', now() at time zone 'Europe/London' + interval '14 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '14 days') at time zone 'Europe/London' + interval '19 hours', 'sold_out'),
  ('5b000000-0000-4000-8000-000000000015', 'sample-stand-up-sunday', '5a000000-0000-4000-8000-000000000001', 'Stand-Up Sunday', 'A relaxed Sunday line-up with a headliner fresh from the Fringe. Sample event for testing, not a real show.', '/sample/comedy.jpg', 'Comedy', 'Lantern Comedy', date_trunc('day', now() at time zone 'Europe/London' + interval '4 days') at time zone 'Europe/London' + interval '19 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '4 days') at time zone 'Europe/London' + interval '19 hours', 'on_sale'),
  ('5b000000-0000-4000-8000-000000000016', 'sample-blue-note-evenings', '5a000000-0000-4000-8000-000000000005', 'Blue Note Evenings', 'Late-night jazz standards with a guest vocalist. Sample event for testing, not a real show.', '/sample/jazz.jpg', 'Jazz', 'Wharf Stage', date_trunc('day', now() at time zone 'Europe/London' + interval '13 days') at time zone 'Europe/London' + interval '20 hours' + interval '30 minutes', date_trunc('day', now() at time zone 'Europe/London' + interval '13 days') at time zone 'Europe/London' + interval '20 hours', 'on_sale');
